def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # A repeated color on a diagonal establishes a ray; continue it in that direction.
    for r in range(h - 1):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == v:
                    rr, cc = r + 2, c + 2 * dc
                    while rr < h and 0 <= cc < w:
                        if out[rr][cc] not in (bg, v):
                            break
                        out[rr][cc] = v
                        rr += 1
                        cc += dc
    return out

