    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    pairs = []
    for r in range(h - 1):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and grid[r + 1][c2] == v:
                    pairs.append((r, c, dc, v))
    for r, c, dc, v in pairs:
        # The adjacent equal-color diagonal is a segment. Extend its open end
        # only when its other continuation is blocked by another color.
        before = (r - 1, c - dc)
        after = (r + 2, c + 2 * dc)
        before_in = 0 <= before[0] < h and 0 <= before[1] < w
        after_in = 0 <= after[0] < h and 0 <= after[1] < w
        before_bg = before_in and grid[before[0]][before[1]] == bg
        after_bg = after_in and grid[after[0]][after[1]] == bg
        before_blocked = before_in and grid[before[0]][before[1]] != bg
        after_blocked = after_in and grid[after[0]][after[1]] != bg
        if before_bg and after_blocked:
            dr, dcol, rr, cc = -1, -dc, r - 1, c - dc
